//
//  GameFeedback.swift
//  2048 — Presentation
//
//  Sound + haptics for game events. Sounds are played as SYSTEM sounds (like Gist It's DoneChime):
//  they follow the Ring/Silent switch and the volume and mix with whatever is playing — no audio
//  session is touched. A merge plays a short tone whose pitch climbs with the merged value
//  (`Resources/merge0…10.caf`, generated by `tools/make_sounds.py`); reaching 2048 plays the shared
//  `DoneChime`. Both can be switched off in Settings.
//

import UIKit
import AudioToolbox
import DesignSystem

public enum GameEvent: Equatable, Sendable {
    /// A move slid tiles without merging.
    case slide
    /// A move merged tiles; the value is the largest tile created.
    case merge(Int)
    case won
    case over
}

@MainActor
public protocol GameFeedbackPlaying: AnyObject {
    func play(_ event: GameEvent)
}

@MainActor
public final class SoundAndHapticFeedback: GameFeedbackPlaying {
    private let settings: FeedbackSettings
    private let light = UIImpactFeedbackGenerator(style: .light)
    private let rigid = UIImpactFeedbackGenerator(style: .rigid)
    private let notification = UINotificationFeedbackGenerator()

    public init(settings: FeedbackSettings) {
        self.settings = settings
        light.prepare()
        rigid.prepare()
    }

    public func play(_ event: GameEvent) {
        if settings.hapticsOn { haptic(event) }
        if settings.soundOn { sound(event) }
    }

    private func haptic(_ event: GameEvent) {
        switch event {
        case .slide:
            light.impactOccurred(intensity: 0.45)
            light.prepare()
        case .merge(let value):
            // Bigger merges land harder.
            let step = Double(GameTokens.step(for: value))
            rigid.impactOccurred(intensity: min(0.55 + step * 0.045, 1))
            rigid.prepare()
        case .won:
            notification.notificationOccurred(.success)
        case .over:
            notification.notificationOccurred(.warning)
        }
    }

    private func sound(_ event: GameEvent) {
        switch event {
        case .slide, .over:
            break
        case .merge(let value):
            let index = min(max(Int(log2(Double(value))) - 2, 0), Self.mergeSounds.count - 1)
            if let id = Self.mergeSounds[index] { AudioServicesPlaySystemSound(id) }
        case .won:
            DoneChime.play()
        }
    }

    private static let mergeSounds: [SystemSoundID?] = (0...10).map { index in
        guard let url = Bundle(for: BundleToken.self).url(forResource: "merge\(index)", withExtension: "caf")
        else { return nil }
        var id: SystemSoundID = 0
        return AudioServicesCreateSystemSoundID(url as CFURL, &id) == kAudioServicesNoError ? id : nil
    }
}

private final class BundleToken {}
